+/**
+ * Base {@link DeclaredTypeDefinitionBuilder} for a declared type assignable to a target container class
+ * (for example {@link java.util.Collection} or {@link java.util.Map}), whose generic type arguments are
+ * exposed as the {@link TypeDefinition#getItems() items} of the built definition.
+ *
+ * @since 2.7.6
+ */
+public abstract class AbstractContainerTypeDefinitionBuilder implements DeclaredTypeDefinitionBuilder {
+
+    @Override
+    public boolean accept(ProcessingEnvironment processingEnv, DeclaredType type) {
+        Elements elements = processingEnv.getElementUtils();
+        TypeElement targetTypeElement = elements.getTypeElement(getTargetClass().getTypeName());
+        TypeMirror targetType = targetTypeElement.asType();
+        Types types = processingEnv.getTypeUtils();
+        TypeMirror erasedType = types.erasure(type);
+        return types.isAssignable(erasedType, targetType);
+    }
+
+    @Override
+    public TypeDefinition build(
+            ProcessingEnvironment processingEnv, DeclaredType type, Map<String, TypeDefinition> typeCache) {
+        TypeDefinition typeDefinition = new TypeDefinition(type.toString());
+        // Generic Type arguments
+        type.getTypeArguments().stream()
+                .map(typeArgument -> TypeDefinitionBuilder.build(
+                        processingEnv, typeArgument, typeCache)) // build the TypeDefinition from typeArgument
+                .filter(Objects::nonNull)
+                .map(TypeDefinition::getType)
+                .forEach(typeDefinition.getItems()::add); // Add into the declared TypeDefinition
+        return typeDefinition;
+    }
+
+    /**
+     * The container class that a {@link DeclaredType} must be assignable to for this builder to accept it.
+     *
+     * @return the target container class, for example {@link java.util.Collection} or {@link java.util.Map}
+     */
+    protected abstract Class<?> getTargetClass();
+}
